-- ============================================================
-- Bucks Haven Farm — initial MySQL / MariaDB schema
-- ============================================================
-- Applied by `npm run db:migrate` (scripts/migrate.mjs), which records it in
-- the schema_migrations table so it only ever runs once. Every statement is
-- CREATE TABLE IF NOT EXISTS: running it against a database that already has
-- these tables never drops or overwrites data.
--
-- Conventions
--   * Primary keys are UUID strings (CHAR(36)), generated by the app. This
--     keeps the IDs from the old Supabase project intact on import.
--   * All DATETIME columns hold UTC. Connections run with time_zone='+00:00'.
--   * DATE / TIME columns are farm-local calendar values (APP_TIME_ZONE).
--   * Requires MySQL 8.0+ or MariaDB 10.5+ (CHECK constraints, JSON).
-- ============================================================

-- ---------- users (replaces Supabase auth.users + public.profiles) ----------
CREATE TABLE IF NOT EXISTS users (
  id                  CHAR(36)     NOT NULL,
  email               VARCHAR(254) NOT NULL,
  name                VARCHAR(200) NOT NULL DEFAULT '',
  role                ENUM('admin','employee') NOT NULL DEFAULT 'employee',
  -- Argon2id PHC string. NULL = no password set yet (e.g. imported from
  -- Supabase); such accounts cannot sign in until an admin sets a password.
  password_hash       VARCHAR(255) NULL,
  password_changed_at DATETIME(3)  NULL,
  created_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  updated_at          DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY users_email_unique (email),
  KEY users_role_name_idx (role, name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- sessions ----------
-- id is the SHA-256 (hex) of the random token stored in the browser cookie,
-- so a leaked database row cannot be replayed as a cookie.
CREATE TABLE IF NOT EXISTS sessions (
  id           CHAR(64)     NOT NULL,
  user_id      CHAR(36)     NOT NULL,
  created_at   DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  last_seen_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  expires_at   DATETIME(3)  NOT NULL,
  user_agent   VARCHAR(255) NULL,
  ip_address   VARCHAR(64)  NULL,
  PRIMARY KEY (id),
  KEY sessions_user_idx (user_id),
  KEY sessions_expires_idx (expires_at),
  CONSTRAINT sessions_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- login throttling ----------
-- One row per throttle key ("email:<address>" or "ip:<address>").
CREATE TABLE IF NOT EXISTS login_attempts (
  throttle_key      VARCHAR(191) NOT NULL,
  failures          INT UNSIGNED NOT NULL DEFAULT 0,
  window_started_at DATETIME(3)  NOT NULL,
  locked_until      DATETIME(3)  NULL,
  PRIMARY KEY (throttle_key),
  KEY login_attempts_window_idx (window_started_at)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- tasks ----------
CREATE TABLE IF NOT EXISTS tasks (
  id          CHAR(36)     NOT NULL,
  title       VARCHAR(300) NOT NULL,
  notes       TEXT         NULL,
  assigned_to CHAR(36)     NULL,
  created_by  CHAR(36)     NULL,
  due_date    DATE         NULL,
  priority    ENUM('low','medium','high') NOT NULL DEFAULT 'medium',
  done        BOOLEAN      NOT NULL DEFAULT FALSE,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY tasks_assigned_idx (assigned_to, done),
  KEY tasks_done_due_idx (done, due_date),
  CONSTRAINT tasks_assigned_fk FOREIGN KEY (assigned_to) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT tasks_created_by_fk FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- shifts (work schedule) ----------
CREATE TABLE IF NOT EXISTS shifts (
  id          CHAR(36)     NOT NULL,
  employee_id CHAR(36)     NOT NULL,
  date        DATE         NOT NULL,
  start_time  TIME         NOT NULL,
  end_time    TIME         NOT NULL,
  notes       TEXT         NULL,
  created_at  DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY shifts_date_idx (date, start_time),
  KEY shifts_employee_date_idx (employee_id, date),
  CONSTRAINT shifts_employee_fk FOREIGN KEY (employee_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- availability ----------
CREATE TABLE IF NOT EXISTS availability (
  id             CHAR(36)    NOT NULL,
  employee_id    CHAR(36)    NOT NULL,
  week_start     DATE        NOT NULL,
  -- {"Mon": {"start": "08:00", "end": "17:00"}, ...}
  available_days JSON        NOT NULL,
  notes          TEXT        NULL,
  created_at     DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY availability_employee_week_idx (employee_id, week_start),
  KEY availability_week_idx (week_start),
  CONSTRAINT availability_employee_fk FOREIGN KEY (employee_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT availability_days_json CHECK (JSON_VALID(available_days))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- time_off_requests ----------
CREATE TABLE IF NOT EXISTS time_off_requests (
  id          CHAR(36)    NOT NULL,
  employee_id CHAR(36)    NOT NULL,
  start_date  DATE        NOT NULL,
  end_date    DATE        NOT NULL,
  reason      TEXT        NULL,
  status      ENUM('pending','approved','denied') NOT NULL DEFAULT 'pending',
  reviewed_by CHAR(36)    NULL,
  created_at  DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY time_off_employee_idx (employee_id, created_at),
  KEY time_off_status_idx (status, start_date),
  CONSTRAINT time_off_employee_fk FOREIGN KEY (employee_id) REFERENCES users (id) ON DELETE CASCADE,
  CONSTRAINT time_off_reviewed_by_fk FOREIGN KEY (reviewed_by) REFERENCES users (id) ON DELETE SET NULL,
  CONSTRAINT time_off_dates_order CHECK (end_date >= start_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- horses ----------
CREATE TABLE IF NOT EXISTS horses (
  id         CHAR(36)     NOT NULL,
  name       VARCHAR(200) NOT NULL,
  notes      TEXT         NULL,
  active     BOOLEAN      NOT NULL DEFAULT TRUE,
  barn       ENUM('log-barn','arena-barn') NULL,
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY horses_active_barn_idx (active, barn, name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- feeding_charts (one chart per horse) ----------
CREATE TABLE IF NOT EXISTS feeding_charts (
  id                   CHAR(36)    NOT NULL,
  horse_id             CHAR(36)    NOT NULL,
  am_feed              TEXT        NULL,
  pm_feed              TEXT        NULL,
  supplements          TEXT        NULL,
  special_notes        TEXT        NULL,
  responsible_employee CHAR(36)    NULL,
  barn                 ENUM('log-barn','arena-barn') NULL,
  created_at           DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY feeding_charts_horse_unique (horse_id),
  KEY feeding_charts_responsible_idx (responsible_employee),
  CONSTRAINT feeding_charts_horse_fk FOREIGN KEY (horse_id) REFERENCES horses (id) ON DELETE CASCADE,
  CONSTRAINT feeding_charts_responsible_fk FOREIGN KEY (responsible_employee) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- feeding_logs (AM/PM done state per horse per day) ----------
CREATE TABLE IF NOT EXISTS feeding_logs (
  id           CHAR(36)    NOT NULL,
  chart_id     CHAR(36)    NULL,
  horse_id     CHAR(36)    NULL,
  employee_id  CHAR(36)    NULL,
  feeding_type ENUM('AM','PM') NOT NULL,
  done         BOOLEAN     NOT NULL DEFAULT FALSE,
  date         DATE        NOT NULL,
  created_at   DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  UNIQUE KEY feeding_logs_horse_type_date_unique (horse_id, feeding_type, date),
  KEY feeding_logs_date_idx (date),
  CONSTRAINT feeding_logs_chart_fk FOREIGN KEY (chart_id) REFERENCES feeding_charts (id) ON DELETE CASCADE,
  CONSTRAINT feeding_logs_horse_fk FOREIGN KEY (horse_id) REFERENCES horses (id) ON DELETE CASCADE,
  CONSTRAINT feeding_logs_employee_fk FOREIGN KEY (employee_id) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- announcements ----------
CREATE TABLE IF NOT EXISTS announcements (
  id         CHAR(36)     NOT NULL,
  title      VARCHAR(300) NOT NULL,
  body       TEXT         NULL,
  created_by CHAR(36)     NULL,
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY announcements_created_idx (created_at),
  CONSTRAINT announcements_created_by_fk FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- clock_logs (clock-in / clock-out records) ----------
CREATE TABLE IF NOT EXISTS clock_logs (
  id         CHAR(36)     NOT NULL,
  user_id    CHAR(36)     NOT NULL,
  user_name  VARCHAR(200) NOT NULL DEFAULT '',
  action     ENUM('in','out') NOT NULL,
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY clock_logs_user_created_idx (user_id, created_at),
  KEY clock_logs_created_idx (created_at),
  CONSTRAINT clock_logs_user_fk FOREIGN KEY (user_id) REFERENCES users (id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------- admin_notes ----------
CREATE TABLE IF NOT EXISTS admin_notes (
  id         CHAR(36)     NOT NULL,
  title      VARCHAR(300) NOT NULL,
  body       TEXT         NULL,
  created_by CHAR(36)     NULL,
  created_at DATETIME(3)  NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  PRIMARY KEY (id),
  KEY admin_notes_created_idx (created_at),
  CONSTRAINT admin_notes_created_by_fk FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
